import { useState, useEffect } from "react";

const API = "http://localhost:5000/api/users";

export default function App() {
  const [users, setUsers] = useState([]);
  const [input, setInput] = useState("");
  const [editId, setEditId] = useState(null);
  const [editInput, setEditInput] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const fetchUsers = async () => {
    const res = await fetch(API);
    const data = await res.json();
    setUsers(data);
  };

  useEffect(() => { fetchUsers(); }, []);

  const showError = (msg) => {
    setError(msg);
    setTimeout(() => setError(""), 3000);
  };

  const addUser = async () => {
    if (!input.trim()) return showError("Please enter a username.");
    setLoading(true);
    const res = await fetch(API, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: input }),
    });
    const data = await res.json();
    setLoading(false);
    if (!res.ok) return showError(data.error);
    setUsers([...users, data]);
    setInput("");
  };

  const deleteUser = async (id) => {
    await fetch(`${API}/${id}`, { method: "DELETE" });
    setUsers(users.filter(u => u.id !== id));
  };

  const startEdit = (user) => {
    setEditId(user.id);
    setEditInput(user.username);
  };

  const saveEdit = async (id) => {
    const res = await fetch(`${API}/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: editInput }),
    });
    const data = await res.json();
    if (!res.ok) return showError(data.error);
    setUsers(users.map(u => u.id === id ? data : u));
    setEditId(null);
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "#0d0d0f",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "'DM Mono', monospace",
      padding: "2rem",
    }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400;500&family=Bebas+Neue&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        ::-webkit-scrollbar { width: 4px; }
        ::-webkit-scrollbar-track { background: #111; }
        ::-webkit-scrollbar-thumb { background: #333; border-radius: 2px; }
        .btn { cursor: pointer; border: none; transition: all 0.15s; }
        .btn:hover { transform: translateY(-1px); }
        .btn:active { transform: translateY(0); }
        .user-row { animation: slideIn 0.25s ease; }
        @keyframes slideIn { from { opacity: 0; transform: translateX(-12px); } to { opacity: 1; transform: translateX(0); } }
        .input-field:focus { outline: none; border-color: #e8ff5a !important; }
        .error-msg { animation: shake 0.3s ease; }
        @keyframes shake { 0%,100%{transform:translateX(0)} 25%{transform:translateX(-6px)} 75%{transform:translateX(6px)} }
      `}</style>

      <div style={{ width: "100%", maxWidth: 540 }}>
        {/* Header */}
        <div style={{ marginBottom: "2.5rem" }}>
          <div style={{ color: "#e8ff5a", fontSize: 11, letterSpacing: 6, textTransform: "uppercase", marginBottom: 8 }}>
            ▶ system
          </div>
          <h1 style={{
            fontFamily: "'Bebas Neue', sans-serif",
            fontSize: "clamp(3rem, 10vw, 5rem)",
            color: "#fff",
            lineHeight: 0.9,
            letterSpacing: 2,
          }}>
            USER<br />
            <span style={{ color: "#e8ff5a" }}>MANAGEMENT</span>
          </h1>
          <div style={{ marginTop: 12, color: "#444", fontSize: 12, letterSpacing: 2 }}>
            {users.length} USER{users.length !== 1 ? "S" : ""} REGISTERED
          </div>
        </div>

        {/* Add User */}
        <div style={{
          display: "flex",
          gap: 8,
          marginBottom: "1.5rem",
          background: "#111",
          border: "1px solid #222",
          borderRadius: 8,
          padding: "1rem",
        }}>
          <input
            className="input-field"
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === "Enter" && addUser()}
            placeholder="enter username..."
            style={{
              flex: 1,
              background: "transparent",
              border: "1px solid #2a2a2a",
              borderRadius: 6,
              padding: "0.6rem 1rem",
              color: "#fff",
              fontFamily: "'DM Mono', monospace",
              fontSize: 13,
              letterSpacing: 1,
            }}
          />
          <button className="btn" onClick={addUser} disabled={loading} style={{
            background: "#e8ff5a",
            color: "#0d0d0f",
            borderRadius: 6,
            padding: "0.6rem 1.2rem",
            fontFamily: "'DM Mono', monospace",
            fontWeight: 500,
            fontSize: 12,
            letterSpacing: 2,
          }}>
            {loading ? "..." : "+ ADD"}
          </button>
        </div>

        {/* Error */}
        {error && (
          <div className="error-msg" style={{
            background: "#2a1010",
            border: "1px solid #5a1a1a",
            borderRadius: 6,
            padding: "0.75rem 1rem",
            color: "#ff6b6b",
            fontSize: 12,
            marginBottom: "1rem",
            letterSpacing: 1,
          }}>
            ⚠ {error}
          </div>
        )}

        {/* User List */}
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {users.length === 0 && (
            <div style={{
              textAlign: "center",
              padding: "3rem",
              color: "#333",
              fontSize: 12,
              letterSpacing: 3,
              border: "1px dashed #1e1e1e",
              borderRadius: 8,
            }}>
              NO USERS YET
            </div>
          )}
          {users.map(user => (
            <div key={user.id} className="user-row" style={{
              background: "#111",
              border: "1px solid #1e1e1e",
              borderRadius: 8,
              padding: "0.85rem 1rem",
              display: "flex",
              alignItems: "center",
              gap: 10,
            }}>
              <div style={{
                width: 28, height: 28,
                borderRadius: "50%",
                background: "#e8ff5a22",
                border: "1px solid #e8ff5a44",
                display: "flex", alignItems: "center", justifyContent: "center",
                color: "#e8ff5a",
                fontSize: 10,
                fontWeight: 500,
                flexShrink: 0,
              }}>
                {user.username[0].toUpperCase()}
              </div>

              {editId === user.id ? (
                <>
                  <input
                    className="input-field"
                    value={editInput}
                    onChange={e => setEditInput(e.target.value)}
                    onKeyDown={e => e.key === "Enter" && saveEdit(user.id)}
                    autoFocus
                    style={{
                      flex: 1,
                      background: "#0d0d0f",
                      border: "1px solid #e8ff5a",
                      borderRadius: 4,
                      padding: "0.3rem 0.6rem",
                      color: "#fff",
                      fontFamily: "'DM Mono', monospace",
                      fontSize: 13,
                    }}
                  />
                  <button className="btn" onClick={() => saveEdit(user.id)} style={{
                    background: "#e8ff5a", color: "#0d0d0f",
                    borderRadius: 4, padding: "0.3rem 0.7rem",
                    fontFamily: "'DM Mono', monospace", fontSize: 11, fontWeight: 500,
                  }}>SAVE</button>
                  <button className="btn" onClick={() => setEditId(null)} style={{
                    background: "transparent", color: "#555",
                    borderRadius: 4, padding: "0.3rem 0.7rem",
                    fontFamily: "'DM Mono', monospace", fontSize: 11,
                    border: "1px solid #222",
                  }}>×</button>
                </>
              ) : (
                <>
                  <span style={{ flex: 1, color: "#ddd", fontSize: 13, letterSpacing: 1 }}>
                    {user.username}
                  </span>
                  <span style={{ color: "#333", fontSize: 10, letterSpacing: 1, marginRight: 4 }}>
                    #{user.id}
                  </span>
                  <button className="btn" onClick={() => startEdit(user)} style={{
                    background: "transparent", color: "#555",
                    borderRadius: 4, padding: "0.3rem 0.6rem",
                    fontFamily: "'DM Mono', monospace", fontSize: 10,
                    border: "1px solid #222",
                  }}>EDIT</button>
                  <button className="btn" onClick={() => deleteUser(user.id)} style={{
                    background: "transparent", color: "#5a1a1a",
                    borderRadius: 4, padding: "0.3rem 0.6rem",
                    fontFamily: "'DM Mono', monospace", fontSize: 10,
                    border: "1px solid #3a1010",
                  }}>DEL</button>
                </>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
